/*
 * CLICK Learn activity loader.
 *
 * The only file index.html loads for the activity layer, and only when a Learn page is shown.
 * It knows which chapter pages have activities (MANIFEST, generated by build-manifest.js) and
 * downloads the stylesheet, engine, kinds and that stage's definitions on demand. A page with
 * no activity downloads nothing further, so static pages stay fast.
 */
(function () {
  "use strict";
  if (window.ClickLearnLoader) return;
  var VERSION = "1";
  var me = document.currentScript;
  var BASE = me && me.src ? me.src.replace(/[^/]*$/, "") : "assets/learn/";
  /*MANIFEST*/ var MANIFEST = {"CH0031":{"stage":"STG001","pages":{"1":{"n":1},"2":{"n":1},"3":{"n":1},"4":{"n":1},"5":{"n":1,"interp":true}}},"CH0032":{"stage":"STG001","pages":{"1":{"n":1},"2":{"n":1,"interp":true},"3":{"n":1,"interp":true},"4":{"n":2},"5":{"n":2}}},"CH0033":{"stage":"STG001","pages":{"2":{"n":1,"interp":true},"3":{"n":1},"4":{"n":1},"5":{"n":2}}},"CH0034":{"stage":"STG001","pages":{"1":{"n":1},"2":{"n":1},"3":{"n":1,"interp":true},"4":{"n":2}}},"CH0035":{"stage":"STG001","pages":{"1":{"n":1},"2":{"n":2,"interp":true},"3":{"n":1},"4":{"n":2},"5":{"n":3,"interp":true}}},"CH0036":{"stage":"STG002","pages":{"1":{"n":1},"3":{"n":1,"interp":true},"4":{"n":2},"5":{"n":2}}},"CH0037":{"stage":"STG002","pages":{"3":{"n":2,"interp":true},"4":{"n":1},"5":{"n":1,"interp":true}}},"CH0038":{"stage":"STG002","pages":{"2":{"n":1},"3":{"n":1,"interp":true},"4":{"n":2}}},"CH0039":{"stage":"STG002","pages":{"2":{"n":1},"3":{"n":2,"interp":true}}},"CH0040":{"stage":"STG002","pages":{"1":{"n":1,"interp":true},"2":{"n":1,"interp":true},"3":{"n":1},"4":{"n":2}}},"CH0041":{"stage":"STG003","pages":{"2":{"n":1,"interp":true},"3":{"n":2},"4":{"n":1,"interp":true},"5":{"n":2}}},"CH0042":{"stage":"STG003","pages":{"2":{"n":1,"interp":true},"3":{"n":2,"interp":true},"4":{"n":1}}},"CH0043":{"stage":"STG003","pages":{"2":{"n":2,"interp":true},"3":{"n":2,"interp":true},"4":{"n":2,"interp":true}}},"CH0044":{"stage":"STG003","pages":{"1":{"n":1},"3":{"n":3,"interp":true},"4":{"n":1},"5":{"n":1}}},"CH0045":{"stage":"STG003","pages":{"3":{"n":1},"4":{"n":3,"interp":true},"5":{"n":2}}},"CH0046":{"stage":"STG004","pages":{"1":{"n":1},"3":{"n":1},"4":{"n":1,"interp":true}}},"CH0047":{"stage":"STG004","pages":{"2":{"n":2},"3":{"n":2,"interp":true},"4":{"n":2}}},"CH0048":{"stage":"STG004","pages":{"3":{"n":1,"interp":true},"4":{"n":2,"interp":true},"5":{"n":1}}},"CH0049":{"stage":"STG004","pages":{"2":{"n":1},"3":{"n":2},"4":{"n":2}}},"CH0050":{"stage":"STG004","pages":{"1":{"n":1},"2":{"n":1},"3":{"n":1},"4":{"n":2,"interp":true}}},"CH0051":{"stage":"STG005","pages":{"1":{"n":1,"interp":true},"3":{"n":2,"interp":true},"4":{"n":1}}},"CH0052":{"stage":"STG005","pages":{"2":{"n":1,"interp":true},"3":{"n":1,"interp":true},"5":{"n":2}}},"CH0053":{"stage":"STG005","pages":{"2":{"n":1,"interp":true},"3":{"n":1,"interp":true},"5":{"n":1}}},"CH0054":{"stage":"STG005","pages":{"1":{"n":1},"2":{"n":1},"4":{"n":1,"interp":true}}},"CH0055":{"stage":"STG005","pages":{"2":{"n":1,"interp":true},"3":{"n":1},"5":{"n":1}}},"CH0056":{"stage":"STG006","pages":{"1":{"n":1,"interp":true},"2":{"n":1,"interp":true},"3":{"n":1,"interp":true},"5":{"n":1,"interp":true}}},"CH0057":{"stage":"STG006","pages":{"3":{"n":2,"interp":true},"4":{"n":1,"interp":true},"5":{"n":1,"interp":true}}},"CH0058":{"stage":"STG006","pages":{"2":{"n":1,"interp":true},"3":{"n":1,"interp":true},"5":{"n":1,"interp":true}}},"CH0059":{"stage":"STG006","pages":{"3":{"n":1,"interp":true},"4":{"n":1,"interp":true},"5":{"n":1,"interp":true}}},"CH0060":{"stage":"STG006","pages":{"3":{"n":1,"interp":true},"4":{"n":1,"interp":true},"5":{"n":1,"interp":true}}},"CH0061":{"stage":"STG006","pages":{"1":{"n":1,"interp":true},"2":{"n":1,"interp":true},"5":{"n":1,"interp":true}}},"CH0115":{"stage":"STG005","pages":{"2":{"n":1,"interp":true},"3":{"n":2,"interp":true},"4":{"n":1}}}}; /*END-MANIFEST*/
  var cache = {}, seq = 0;

  function load(name, isCss) {
    var url = BASE + name;
    if (cache[url]) return cache[url];
    cache[url] = new Promise(function (resolve, reject) {
      if (isCss) {
        var l = document.createElement("link");
        l.rel = "stylesheet"; l.href = url + "?v=" + VERSION; l.onload = resolve; l.onerror = function () { reject(new Error("load failed " + name)); };
        document.head.appendChild(l);
      } else {
        var s = document.createElement("script");
        s.src = url + "?v=" + VERSION; s.async = false; s.onload = resolve; s.onerror = function () { reject(new Error("load failed " + name)); };
        document.head.appendChild(s);
      }
    });
    cache[url].catch(function () { delete cache[url]; });
    return cache[url];
  }

  window.ClickLearnLoader = {
    version: VERSION,
    manifest: MANIFEST,
    hasActivities: function (chapter, page) { var e = MANIFEST[chapter]; return !!(e && e.pages && e.pages[page]); },
    // o: { container, stage, chapter, page, heading, userId }
    mount: function (o) {
      var entry = MANIFEST[o.chapter], pg = entry && entry.pages && entry.pages[o.page];
      if (!pg) { o.container.hidden = true; o.container.textContent = ""; return Promise.resolve(0); }
      var mine = String(++seq);
      o.container.dataset.token = mine; o.container.hidden = false;
      window.ClickLearnAssetVersion = VERSION;
      var chain = Promise.all([load("activities.css", true), load("engine.js")])
        .then(function () { return load("kinds-visual.js"); })
        .then(function () { return pg.interp ? load("c-interp.js").then(function () { return load("kinds-code.js"); }) : null; })
        .then(function () { return load("defs/" + o.chapter.toLowerCase() + ".js"); });
      return chain.then(function () {
        if (o.container.dataset.token !== mine || !document.body.contains(o.container)) return 0;
        return window.ClickLearn.mountPage(o.container, { stage: entry.stage, chapter: o.chapter, page: o.page, heading: o.heading, userId: o.userId });
      }).catch(function (e) {
        if (window.console) console.warn("[learn-activity] could not load activities:", e && e.message);
        o.container.hidden = true; o.container.textContent = "";
        return 0;
      });
    },
  };
})();
